import{_ as r,C as s,c as a,o as i,a3 as o,G as e}from"./chunks/framework.Dokpd4od.js";const y=JSON.parse('{"title":"Configure a product for inventory","description":"","frontmatter":{},"headers":[],"relativePath":"master/supply-chain/inventories/products/configure-product.md","filePath":"master/supply-chain/inventories/products/configure-product.md","lastUpdated":1792041590000}'),d={name:"master/supply-chain/inventories/products/configure-product.md"};function l(g,t,c,u,h,p){const n=s("ImagePopup");return i(),a("div",null,[t[0]||(t[0]=o('<h1 id="configure-a-product-for-inventory" tabindex="-1">Configure a product for inventory <a class="header-anchor" href="#configure-a-product-for-inventory" aria-label="Permalink to &quot;Configure a product for inventory&quot;">​</a></h1><p>A product form has a section named <strong>Inventory</strong>. It decides whether the product has stock, how it is tracked and how it moves. This page covers that section and the stock tabs of a product. The base fields (name, price, taxes) are in the Sales guide.</p><blockquote><p><strong>In simple words:</strong> Switch on <strong>Track Inventory</strong> and Aureus starts counting this product.</p></blockquote><p>Open a product with <code>Inventory → Products → Products</code>, then <strong>New Product</strong> or <strong>Edit</strong>.</p><h2 id="settings" tabindex="-1">Settings <a class="header-anchor" href="#settings" aria-label="Permalink to &quot;Settings&quot;">​</a></h2><p>The <strong>Inventory</strong> section shows only when <strong>Type</strong> is <strong>Goods</strong>. A service has no stock. <strong>Track By</strong> needs <code>Inventory → Settings → Manage Traceability → Lots &amp; Serial Numbers</code> to be on. See <a href="./../get-started/inventory-settings.html">Inventory settings</a>.</p><h2 id="overview" tabindex="-1">Overview <a class="header-anchor" href="#overview" aria-label="Permalink to &quot;Overview&quot;">​</a></h2><p>The product list has the tabs <strong>Default</strong>, <strong>Goods</strong>, <strong>Services</strong>, <strong>Favorites</strong>, <strong>Archived</strong>, <strong>Inventory Management</strong>, <strong>Components</strong> and <strong>POS</strong>.</p>',8)),e(n,{src:"/images1/inventory/prod_list.png",alt:"Inventory products list with On Hand and Forecasted columns"}),t[1]||(t[1]=o('<ul><li><strong>On Hand:</strong> Quantity sitting in your internal locations now.</li><li><strong>Forecasted:</strong> What you expect to hold after incoming and outgoing orders.</li></ul><p>Both columns show a dash for products that do not track inventory.</p><h2 id="set-up-the-inventory-section" tabindex="-1">Set up the Inventory section <a class="header-anchor" href="#set-up-the-inventory-section" aria-label="Permalink to &quot;Set up the Inventory section&quot;">​</a></h2><ol><li>Go to <code>Inventory → Products → Products</code> and open a product in <strong>Edit</strong>.</li><li>Scroll to the <strong>Inventory</strong> section.</li></ol>',4)),e(n,{src:"/images1/inventory/prod_inventory_section.png",alt:"Product edit page Inventory section with Track Inventory on, Track By, Routes and Logistics filled"}),t[2]||(t[2]=o('<h3 id="tracking" tabindex="-1">Tracking <a class="header-anchor" href="#tracking" aria-label="Permalink to &quot;Tracking&quot;">​</a></h3><ul><li><strong><em>Track Inventory:</em></strong> Turn on to manage stock for this product. A storable product is one that needs inventory management.</li><li><strong><em>Track By:</em></strong> Choose how you identify stock. Shows when Track Inventory and the lots setting are on. <ul><li><strong>By Quantity:</strong> Stock is counted in numbers only.</li><li><strong>By Lots:</strong> Units share a batch number.</li><li><strong>By Unique Serial Number:</strong> Each unit has its own number.</li></ul></li></ul><div class="warning custom-block"><p class="custom-block-title">WARNING</p><p>Choose <strong>Track By</strong> before the first stock arrives. Changing it later while stock exists can leave old quantities without a lot or serial number. See <a href="./../tracking/lots-and-serial-numbers.html">Lots and serial numbers</a>.</p></div><h3 id="operations" tabindex="-1">Operations <a class="header-anchor" href="#operations" aria-label="Permalink to &quot;Operations&quot;">​</a></h3><ul><li><strong><em>Routes:</em></strong> Tick the routes this product follows, such as Cross-Dock. Routes appear based on your installed apps and settings.</li></ul><h3 id="logistics" tabindex="-1">Logistics <a class="header-anchor" href="#logistics" aria-label="Permalink to &quot;Logistics&quot;">​</a></h3><ul><li><strong><em>Responsible:</em></strong> The user in charge of this product&#39;s stock.</li><li><strong><em>Weight:</em></strong> Weight of one unit.</li><li><strong><em>Volume:</em></strong> Volume of one unit.</li><li><strong><em>Customer Lead Time (Days):</em></strong> The promised time between confirming a sales order and delivery.</li></ul><ol start="3"><li>Click <strong>Save changes</strong>.</li></ol><h2 id="update-the-quantity" tabindex="-1">Update the quantity <a class="header-anchor" href="#update-the-quantity" aria-label="Permalink to &quot;Update the quantity&quot;">​</a></h2><p>The <strong>Update Quantity</strong> button sits in the header of a storable product. It sets how much you hold.</p>',10)),e(n,{src:"/images1/inventory/prod_update_quantity_button.png",alt:"Product view header with Update Quantity, chatter, Print Labels and Delete buttons"}),t[3]||(t[3]=o("<ul><li>With <strong>Locations</strong> or <strong>Packages</strong> on, the button opens the <strong>Quantities</strong> tab. Click <strong>Add Quantity</strong>, then fill <strong>Location</strong> (default WH/Stock), <strong>Package</strong> and <strong>On Hand Quantity</strong>. Click <strong>Create</strong>.</li><li>Without those settings, it opens a window titled <strong>Update Product Quantity</strong> with <strong>On Hand Quantity</strong>. Click <strong>Update</strong>.</li><li>With tracked lots and <strong>Track By</strong> not set to By Quantity, the button also opens <strong>Quantities</strong>.</li></ul>",1)),e(n,{src:"/images1/inventory/prod_add_quantity_modal.png",alt:"Create Product Quantity window with Location WH/Stock and On Hand Quantity filled"}),t[4]||(t[4]=o('<p>If a quantity already exists for the same place, you get a warning. Edit the existing line instead.</p><div class="tip custom-block"><p class="custom-block-title">TIP</p><p>Use <strong>Update Quantity</strong> only to load opening stock. For counts, use <a href="./../adjustments/inventory-adjustments.html">Inventory adjustments</a>.</p></div><h2 id="product-tabs" tabindex="-1">Product tabs <a class="header-anchor" href="#product-tabs" aria-label="Permalink to &quot;Product tabs&quot;">​</a></h2><p>A product record has sub tabs next to <strong>View</strong> and <strong>Edit</strong>.</p><table tabindex="0"><thead><tr><th>Tab</th><th>What it shows</th></tr></thead><tbody><tr><td><strong>Attributes</strong></td><td>Attributes that create variants. Click <strong>Add Attribute</strong>.</td></tr><tr><td><strong>Variants</strong></td><td>Each variant with price, <strong>On Hand</strong> and <strong>Forecasted</strong></td></tr><tr><td><strong>Bills of Materials</strong></td><td>Recipes that use this product. Needs Manufacturing.</td></tr><tr><td><strong>Vendors</strong></td><td>Supplier prices. Click <strong>Add Vendor</strong>. Needs Purchase.</td></tr><tr><td><strong>Quantities</strong></td><td>Stock per location, package and reserved quantity</td></tr><tr><td><strong>IN/OUT</strong></td><td>Every move of this product</td></tr></tbody></table><p>The <strong>Quantities</strong> tab has the tabs <strong>Internal Locations</strong>, <strong>Transit Locations</strong>, <strong>On Hand</strong>, <strong>To Count</strong> and <strong>To Apply</strong>. The <strong>IN/OUT</strong> tab has <strong>To Do</strong>, <strong>Done</strong>, <strong>Incoming</strong>, <strong>Outgoing</strong> and <strong>Internal</strong>.</p>',6)),e(n,{src:"/images1/inventory/prod_quantities_tab.png",alt:"Product Quantities tab showing locations with on hand and reserved quantity"}),t[5]||(t[5]=o('<h2 id="print-labels" tabindex="-1">Print labels <a class="header-anchor" href="#print-labels" aria-label="Permalink to &quot;Print labels&quot;">​</a></h2><p>Click <strong>Print Labels</strong> in the header. Enter <strong>Number of Labels</strong> and choose <strong>Format</strong>. Options are Dymo, 2x7 with price, 4x7 with price, 4x12 and 4x12 with price. Click <strong>Submit</strong>.</p><h2 id="behind-the-scenes" tabindex="-1">Behind the scenes <a class="header-anchor" href="#behind-the-scenes" aria-label="Permalink to &quot;Behind the scenes&quot;">​</a></h2><p>Stock lives as a quantity per product and location. Receipts add to it, deliveries remove from it, and counts correct it.</p><h2 id="see-also" tabindex="-1">See also <a class="header-anchor" href="#see-also" aria-label="Permalink to &quot;See also&quot;">​</a></h2><ul><li><a href="./../../../sales/sales/products-prices/manage-products.html">Manage products in Sales</a></li><li><a href="./product-categories.html">Product categories</a></li><li><a href="./../tracking/lots-and-serial-numbers.html">Lots and serial numbers</a></li><li><a href="./../adjustments/inventory-adjustments.html">Inventory adjustments</a></li></ul>',6))])}const b=r(d,[["render",l]]);export{y as __pageData,b as default};
